/*
 * lcd_fonts.h - the larger fonts of the CrowPanel's LCD (lcd.font = 20, 24,
 * 32), generated by tools/make_lcd_font_big.py from Terminus Font (bold).
 * Each returns the rows of a character (rows of (width + 7) / 8 bytes, bit
 * 7 of the first byte leftmost), or NULL when the font does not have it.
 */
#ifndef LCD_FONTS_H
#define LCD_FONTS_H

#include <stdint.h>

const uint8_t *font10x20_glyph(uint16_t cp);
const uint8_t *font12x24_glyph(uint16_t cp);
const uint8_t *font16x32_glyph(uint16_t cp);

#endif
